139	        ..JoinOptions::default()
140	    };
141	    let mut i = 0;
142	    while i < args.len() {
143	        match args[i].as_str() {
144	            "--role" => {
145	                let value = args.get(i + 1).context("--role requires a value")?;
146	                if value.starts_with("--") {
147	                    bail!("--role requires a value");
148	                }
149	                options.role = Some(value.clone());
150	                i += 2;
151	            }
152	            "--client" => {
153	                let value = args.get(i + 1).context("--client requires a value")?;
154	                if value.starts_with("--") {
155	                    bail!("--client requires a value");
156	                }
157	                match value.as_str() {
158	                    "claude" | "gemini" | "codex" | "opencode" => {
159	                        options.client_type = Some(value.clone())
160	                    }
161	                    _ => bail!("invalid --client value: {value}"),
162	                }
163	                i += 2;
164	            }
165	            "--protocol-version" => {
166	                let value = args
167	                    .get(i + 1)
168	                    .context("--protocol-version requires a value")?;
169	                if value.starts_with("--") {
170	                    bail!("--protocol-version requires a value");
171	                }
172	                options.protocol_version = Some(
173	                    value
174	                        .parse()
175	                        .with_context(|| format!("invalid --protocol-version value: {value}"))?,
176	                );
177	                i += 2;
178	            }
179	            flag => bail!("unknown join flag: {flag}"),
180	        }
181	    }
182	    Ok(options)
183	}
