 472	        match current_token.as_deref() {
 473	            Some(current) if current == expected => {}
 474	            Some(_) | None => bail!(
 475	                "Session replaced. Another terminal joined as {agent_id}. \
 476	                 Re-join with a different ID (e.g. squad join {agent_id}-2 --role <your-role>)."
 477	            ),
 478	        }
 479	    }
 480	    let sessions = sessions_dir(workspace);
 481	    if let Some(token) = expected_token {
 482	        squad::session::validate(&sessions, agent_id, token)?;
 483	    }
 484	    Ok(())
 485	}
