 339	    /// Atomically read and mark messages as read using a transaction.
 340	    pub fn receive_messages(&self, agent_id: &str) -> Result<Vec<MessageRecord>> {
 341	        self.require_active_agent(agent_id)?;
 342	        let tx = self.conn.unchecked_transaction()?;
 343	        let mut stmt = tx.prepare(
 344	            "SELECT id, from_agent, to_agent, content, created_at, read, kind, task_id, reply_to
 345	             FROM messages WHERE to_agent = ?1 AND read = 0 ORDER BY created_at, id",
 346	        )?;
 347	        let messages: Vec<MessageRecord> = stmt
 348	            .query_map([agent_id], |row| {
 349	                Ok(MessageRecord {
 350	                    id: row.get(0)?,
 351	                    from_agent: row.get(1)?,
 352	                    to_agent: row.get(2)?,
 353	                    content: row.get(3)?,
 354	                    created_at: row.get(4)?,
 355	                    read: row.get(5)?,
 356	                    kind: row.get(6)?,
 357	                    task_id: row.get(7)?,
 358	                    reply_to: row.get(8)?,
 359	                })
 360	            })?
 361	            .collect::<Result<Vec<_>, _>>()?;
 362	        drop(stmt);
 363	
 364	        if !messages.is_empty() {
 365	            let ids: Vec<i64> = messages.iter().map(|msg| msg.id).collect();
 366	            let placeholders = std::iter::repeat_n("?", ids.len())
 367	                .collect::<Vec<_>>()
 368	                .join(", ");
 369	            let sql =
 370	                format!("UPDATE messages SET read = 1 WHERE read = 0 AND id IN ({placeholders})");
 371	            tx.execute(&sql, params_from_iter(ids))?;
 372	        }
 373	        tx.commit()?;
 374	        Ok(messages)
 375	    }
