 380	        let has: bool = self.conn.query_row(
 381	            "SELECT COUNT(*) > 0 FROM messages WHERE to_agent = ?1 AND read = 0",
 382	            [agent_id],
 383	            |row| row.get(0),
 384	        )?;
 385	        Ok(has)
 386	    }
