 25	/// Delete a session token file.
 26	pub fn delete_token(sessions_dir: &Path, agent_id: &str) -> Result<()> {
 27	    let path = sessions_dir.join(agent_id);
 28	    if path.exists() {
 29	        std::fs::remove_file(&path)?;
 30	    }
 31	    Ok(())
 32	}
 33	
 34	/// Delete all session token files.
 35	pub fn delete_all(sessions_dir: &Path) -> Result<()> {
 36	    if sessions_dir.exists() {
 37	        for entry in std::fs::read_dir(sessions_dir)? {
 38	            let entry = entry?;
 39	            if entry.file_type()?.is_file() {
 40	                std::fs::remove_file(entry.path())?;
 41	            }
 42	        }
 43	    }
 44	    Ok(())
 45	}
