 32	pub fn list_roles(workspace: &Path) -> Vec<String> {
 33	    let mut roles: Vec<String> = BUILTIN_ROLES.iter().map(|s| s.to_string()).collect();
 34	    let custom_dir = workspace.join(".squad").join("roles");
 35	    if let Ok(entries) = std::fs::read_dir(&custom_dir) {
 36	        for entry in entries.flatten() {
 37	            if let Some(name) = entry.path().file_stem() {
 38	                let name = name.to_string_lossy().to_string();
 39	                if !roles.contains(&name) {
 40	                    roles.push(name);
 41	                }
 42	            }
 43	        }
 44	    }
 45	    roles.sort();
 46	    roles
