 11	pub fn init_workspace_with_options(workspace: &Path, refresh_roles: bool) -> Result<()> {
 12	    let squad_dir = workspace.join(".squad");
 13	    let roles_dir = squad_dir.join("roles");
 14	    let teams_dir = squad_dir.join("teams");
 15	
 16	    std::fs::create_dir_all(&roles_dir)
 17	        .with_context(|| format!("failed to create {}", roles_dir.display()))?;
 18	    std::fs::create_dir_all(&teams_dir)
 19	        .with_context(|| format!("failed to create {}", teams_dir.display()))?;
 20	    let sessions_dir = squad_dir.join("sessions");
 21	    std::fs::create_dir_all(&sessions_dir)
 22	        .with_context(|| format!("failed to create {}", sessions_dir.display()))?;
 23	
 24	    // Write builtin role templates. Plain init is non-destructive; refresh rewrites builtins only.
 25	    for role in roles::BUILTIN_ROLES {
 26	        let path = roles_dir.join(format!("{role}.md"));
 27	        if !path.exists() || refresh_roles {
 28	            if let Some(content) = roles::default_role_prompt(role) {
 29	                std::fs::write(&path, content)
 30	                    .with_context(|| format!("failed to write {}", path.display()))?;
 31	            }
 32	        }
 33	    }
 34	
 35	    // Write builtin team templates (skip if already exist)
 36	    for team_name in teams::BUILTIN_TEAMS {
 37	        let path = teams_dir.join(format!("{team_name}.yaml"));
 38	        if !path.exists() {
 39	            if let Some(team) = teams::default_team(team_name) {
 40	                let content = serde_yaml::to_string(&team)
 41	                    .with_context(|| format!("failed to serialize team: {team_name}"))?;
 42	                std::fs::write(&path, content)
 43	                    .with_context(|| format!("failed to write {}", path.display()))?;
 44	            }
 45	        }
 46	    }
 47	
 48	    // Add .squad/ to .gitignore
 49	    append_if_missing(workspace, ".gitignore", ".squad/")?;
 50	
 51	    // Add squad instructions to agent config files
 52	    let squad_section = SQUAD_AGENT_INSTRUCTIONS;
 53	    let marker = "## Squad Collaboration";
 54	    for filename in &["CLAUDE.md", "AGENTS.md", "GEMINI.md"] {
 55	        append_section_if_missing(workspace, filename, marker, squad_section)?;
 56	    }
 57	
 58	    Ok(())
 59	}
